head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)

scwin.fn_GetPar, scwin.fn_SetPar, scwin.strCdSch;
scwin.fr_SecuGrpId; //증권그룹ID
scwin.fr_mktTpCd; // 유가종목, 코스닥종목, 유가+코스닥전체종목 조회구분값 
scwin.vScrenID = "ULDSTF05108.xml";

scwin.onpageload = function() {
    scwin.init();
};

scwin.onpageunload = function() {
};

scwin.fn_list_sync = async function() {
    //let url = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listIsurInstForNewList&inputMessageId=KIND_STK_NEWLIST_ISUR_INST_OUT";
    //url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    //url += "&COM_NM=" + txb_COM_NM.getValue();
    //url += "&SECUGRP_ID=" + scwin.fr_SecuGrpId;
    //url += "&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.fr_mktTpCd;
    //dts_IsurInst.DataID = encodeURI(url);
    //dts_IsurInst.reset();

    dma_listReq.set("isurCd", txb_ISUR_CD.getValue());
    dma_listReq.set("comNm", txb_COM_NM.getValue());
    dma_listReq.set("secugrpId", scwin.fr_SecuGrpId);
    dma_listReq.set("spotIsuTrdMktTpCd", scwin.fr_mktTpCd);

    const sbmOptions = {
        id: "sbm_selectListNewlistingKindstk",
        action: "/api/listing/common/pop/issur/select-list-newlisting-kindstk",
        method: "get",
        ref: "dma_listReq",
        target: "dlt_listRes=body",
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions);

    scwin.dts_IsurInst_OnLoadCompleted();
};

scwin.dts_IsurInst_OnLoadCompleted = function(rowcount) {
    if (dlt_listRes.errorMsg) {
        $c.win.alert(dlt_listRes.errorMsg);
    } else {
        //txb_TotCnt.setValue("총 " + dlt_listRes.getRowCount() + " 건");
        txb_TotCnt.setValue(dlt_listRes.getRowCount());

        // 초기1회 초기값으로 설정된 회사코드를 검색한다.
        if (scwin.strCdSch != "") {
            for (let i = 1; i <= dlt_listRes.getTotalRow(); i++) {
                if (scwin.strCdSch == dlt_listRes.getCellData(i, 1)) {
                    dlt_listRes.setRowPosition(i, 0);
                    break;
                }
            }
            scwin.strCdSch = "";
        }
    }
};

/* 
 * 목록 더블클릭
 */
scwin.grd_IsuInst_OnDblClick = async function(row, colid) {
    // 부모창들이 맞춰서 TO-BE로 전환되면 필요없어짐
    let arrPar = new Array();
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = {
            ISUR_CD: dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "isurCd"),
            COM_NM: dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "comNm"),
            LIST_DD: dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "listDd"),
            PRELM_INVSTG_BZ_PROCS_NO: dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "prelmInvstgBzProcsNo"),
            DBCLICKYN: "Y"
        };
        scwin.fn_SetPar(arrPar);
    }

    // TO-BE로 전환한 데이터
    const rtn = {
        ISUR_CD: dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "isurCd"),
        COM_NM: dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "comNm"),
        LIST_DD: dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "listDd"),
        PRELM_INVSTG_BZ_PROCS_NO: dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "prelmInvstgBzProcsNo"),
        DBCLICKYN: "Y"
    };
    await $c.win.closePopup(rtn);
};

/* 
 * 조회 버튼
 */
scwin.img_Search_onclick = function() {
    scwin.fn_list_sync();
};

/* 
 * 화면 초기화
 */
scwin.init = function() {
    $c.win.setEnterKeyEvent(grp_search, scwin.img_Search_onclick);
    window.document.body.scroll = "no";
    let arrPar = new Array();
    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    //let parentWin = $c.frame.path("../");
    let parentWin = $c.win.getParent();
    scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
    scwin.fn_SetPar = parentWin.scwin.fn_SetPar;

    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
        strSch = (arrPar.length >= 1 ? arrPar[0] : "");
        scwin.fr_SecuGrpId = (arrPar.length >= 3 ? arrPar[2] : "");
        scwin.fr_mktTpCd = (arrPar.length >= 4 ? arrPar[3] : "");
    }

    // TO-BE 파라미터 받아오기
    let getParam = $c.data.getParameter();
    if ($c.util.isNotEmpty(getParam)) {
        scwin.fr_SecuGrpId = getParam.secugrpId ?? "";
        scwin.fr_mktTpCd = getParam.mktTpCd ?? "";
    }

    scwin.fn_list_sync();
};
